import pathlib,json,yaml,hashlib
class UniqueLoader(yaml.SafeLoader):pass
def mapping(loader,node,deep=False):
 out={}
 for kn,vn in node.value:
  k=loader.construct_object(kn,deep=deep)
  assert k not in out,"duplicate YAML key"
  out[k]=loader.construct_object(vn,deep=deep)
 return out
UniqueLoader.add_constructor(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG,mapping)
def load_yaml(file):
 docs=[d for d in yaml.load_all(pathlib.Path(file).read_text(encoding="utf8"),Loader=UniqueLoader) if d is not None]
 assert all(isinstance(d,dict) and d.get("kind") and d.get("apiVersion") and d.get("metadata",{}).get("name") for d in docs)
 identities=[(d["kind"],d["metadata"].get("namespace",""),d["metadata"]["name"]) for d in docs]
 assert len(identities)==len(set(identities)),"duplicate resource identity"
 return docs
def canon(v):
 if isinstance(v,dict):return {k:canon(x) for k,x in sorted(v.items())}
 if isinstance(v,list):
  out=[canon(x) for x in v]
  if out and all(isinstance(x,dict) and "name" in x for x in out):out.sort(key=lambda x:x["name"])
  return out
 return v
def prepare(docs):
 out=[]
 for d in docs:
  d=canon(d)
  if d["kind"]=="Service":
   d["spec"].setdefault("type","ClusterIP")
   for port in d["spec"].get("ports",[]):port.setdefault("protocol","TCP")
  if d["kind"]=="Pod":d["spec"].setdefault("hostNetwork",False)
  out.append(d)
 return sorted(out,key=lambda d:(d["kind"],d["metadata"].get("namespace",""),d["metadata"]["name"]))
def contract(file,want):
 actual=prepare(load_yaml(file));expected=prepare(want)
 # Parsed typed structures, not source equality; resource/namespace bounds included.
 assert json.dumps(actual,sort_keys=True)==json.dumps(expected,sort_keys=True),"manifest contract differs"
 return actual

